\version "2.27.2"
% automatically converted by musicxml2ly from 45d-Repeats-MultipleEndings.xml
\pointAndClickOff

\header {
  texidoc = "Multiple alternative endings. The first alternative starts and ends
    at bar 2; the second continues until bar 5, the third, fifth, and seventh
    until bar 9, the fourth and sixth until bar 10, and the eighth is
    discontinued after one bar.

    In this test, the <ending> elements don't contain text except the one in
    bar 10, which holds ‘Foo’."
}
\layout {
  \context {
    \Staff
    printKeyCancellation = ##f
  }
  \context {
    \Score
    doubleRepeatBarType = ":|.|:"
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative c' {
  \repeat volta 8 {
    \clef "treble" \time 4/4 \key c \major R1 | % 1
    \alternative {
      \volta 1 {
        R1 | % 2
      }
      \volta 2 {
        R1 | % 3
        R1 | % 4
        R1 | % 5
      }
      \volta 3,5,7 {
        R1 | % 6
        R1 | % 7
        R1 | % 8
        R1 | % 9

        \barNumberCheck #10
      }
      \volta 4,6 {
        \once \override Score.VoltaBracket.text = \markup Foo R1 | % 10
      }
      \volta 8 {
        R1 | % 11
      }
    }
  }
  R1 \bar "|."
}


% The score definition
\score {
  <<
    \new Staff = "P1" <<
      \context Staff <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceOne" {
          \PartPOneVoiceOne
        }
      >>
    >>
  >>
  \layout {}
